rep("_al, _am, _pp = bl.get('a_loamm'), bl.get('a_mclmm'), bl.get('p_oa')", "_al, _am, _pp, _mf = bl.get('a_loamm'), bl.get('a_mclmm'), bl.get('p_oa'), bl.get('a_moacf')")
rep("def first(tok):",
    "chk('(d9) S6F receipt a_moacf == [%g, %g] and MOACF_APPLIED in the log, every copy a_moacf %g %g (none of either when 0)' % ((A.amoacf,) * 4),\n"
    "    (_mf == [A.amoacf, A.amoacf] and len(mk_mf) >= 1 and all(fl(x) == A.amoacf and fl(y) == A.amoacf for x, y in mk_mf)) if A.amoacf else (_mf is None and not mk_mf),\n"
    "    f'receipt {_mf} log {mk_mf}')\n"
    "def first(tok):")
rep("pos = {t: first(t) for t in ('EOA_APPLIED', 'CVX_APPLIED', 'LOAMM_APPLIED', 'MCLMM_APPLIED', 'S6F_BLEND_OK', 'S6F_DONE')}",
    "pos = {t: first(t) for t in ('EOA_APPLIED', 'CVX_APPLIED', 'LOAMM_APPLIED', 'MCLMM_APPLIED', 'MOACF_APPLIED', 'S6F_BLEND_OK', 'S6F_DONE')}")
rep("(['MCLMM_APPLIED'] if A.amclmm else []) + ['S6F_BLEND_OK', 'S6F_DONE']",
    "(['MCLMM_APPLIED'] if A.amclmm else []) + (['MOACF_APPLIED'] if A.amoacf else []) + ['S6F_BLEND_OK', 'S6F_DONE']")
rep("| ({'p_oa'} if A.poa != 1 else set())", "| ({'p_oa'} if A.poa != 1 else set()) | ({'a_moacf'} if A.amoacf else set())")
rep("for nm, alt in (('dose (a_oa %g vs .3)' % A.aoa, (0.3, A.aloamm, A.amclmm, A.poa)), ('LOAMM (a %g vs 0)' % A.aloamm, (A.aoa, 0.0, A.amclmm, A.poa)), "
    "('MCLMM (a %g vs 0)' % A.amclmm, (A.aoa, A.aloamm, 0.0, A.poa)), ('CVX (p %g vs 1)' % A.poa, (A.aoa, A.aloamm, A.amclmm, 1.0))):\n"
    "    if alt == (A.aoa, A.aloamm, A.amclmm, A.poa):",
    "for nm, alt in (('dose (a_oa %g vs .3)' % A.aoa, (0.3, A.aloamm, A.amclmm, A.poa, A.amoacf)), ('LOAMM (a %g vs 0)' % A.aloamm, (A.aoa, 0.0, A.amclmm, A.poa, A.amoacf)), "
    "('MCLMM (a %g vs 0)' % A.amclmm, (A.aoa, A.aloamm, 0.0, A.poa, A.amoacf)), ('CVX (p %g vs 1)' % A.poa, (A.aoa, A.aloamm, A.amclmm, 1.0, A.amoacf)), "
    "('MOACF (a %g vs 0)' % A.amoacf, (A.aoa, A.aloamm, A.amclmm, A.poa, 0.0))):\n"
    "    if alt == (A.aoa, A.aloamm, A.amclmm, A.poa, A.amoacf):")
